package com.omnistyle

import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.uimanager.annotations.ReactProp
import com.facebook.react.viewmanagers.OmniPdfViewManagerDelegate
import com.facebook.react.viewmanagers.OmniPdfViewManagerInterface

/**
 * Bridge between Fabric and `OmniPdfView`: props, commands and events.
 * `OmniPdfViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/media/pdf/native/OmniPdfViewNativeComponent.ts`.
 */
@ReactModule(name = OmniPdfViewManager.NAME)
class OmniPdfViewManager :
  SimpleViewManager<OmniPdfView>(),
  OmniPdfViewManagerInterface<OmniPdfView> {

  private val delegate = OmniPdfViewManagerDelegate(this)

  override fun getDelegate(): ViewManagerDelegate<OmniPdfView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): OmniPdfView = OmniPdfView(context)

  override fun onDropViewInstance(view: OmniPdfView) {
    view.release()
    super.onDropViewInstance(view)
  }

  // ── props ──

  @ReactProp(name = "src")
  override fun setSrc(view: OmniPdfView, value: String?) = view.setSource(value)

  @ReactProp(name = "password")
  override fun setPassword(view: OmniPdfView, value: String?) = view.setPassword(value)

  @ReactProp(name = "initialPage", defaultInt = 1)
  override fun setInitialPage(view: OmniPdfView, value: Int) = view.setInitialPage(value)

  @ReactProp(name = "controls", defaultBoolean = true)
  override fun setControls(view: OmniPdfView, value: Boolean) = view.setControls(value)

  @ReactProp(name = "nightMode")
  override fun setNightMode(view: OmniPdfView, value: Boolean) = view.setNightMode(value)

  @ReactProp(name = "fit")
  override fun setFit(view: OmniPdfView, value: String?) = view.setFit(value)

  @ReactProp(name = "direction")
  override fun setDirection(view: OmniPdfView, value: String?) = view.setDirection(value)

  @ReactProp(name = "maxZoom", defaultFloat = 5f)
  override fun setMaxZoom(view: OmniPdfView, value: Float) = view.setMaxZoom(value)

  @ReactProp(name = "playlistIndex", defaultInt = -1)
  override fun setPlaylistIndex(view: OmniPdfView, value: Int) = view.setPlaylist(value, view.playlistCount)

  @ReactProp(name = "playlistCount")
  override fun setPlaylistCount(view: OmniPdfView, value: Int) = view.setPlaylist(view.playlistIndex, value)

  @ReactProp(name = "speechLanguage")
  override fun setSpeechLanguage(view: OmniPdfView, value: String?) = view.setSpeechLanguage(value)

  @ReactProp(name = "speechVoice")
  override fun setSpeechVoice(view: OmniPdfView, value: String?) = view.setSpeechVoice(value)

  // ── commands ──

  override fun goToPage(view: OmniPdfView, page: Int) = view.goToPage(page)

  override fun search(view: OmniPdfView, query: String) = view.search(query)

  override fun searchNext(view: OmniPdfView) = view.searchNext()

  override fun searchPrevious(view: OmniPdfView) = view.searchPrevious()

  override fun clearSearch(view: OmniPdfView) = view.clearSearch()

  override fun setZoom(view: OmniPdfView, scale: Float) = view.setZoom(scale)

  override fun setFullscreen(view: OmniPdfView, fullscreen: Boolean) = view.setFullscreen(fullscreen)

  override fun startReadAloud(view: OmniPdfView) = view.startReadAloud()

  override fun stopReadAloud(view: OmniPdfView) = view.stopReadAloud()

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    OmniPdfView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "OmniPdfView"
  }
}
